//! [`crate::Group::Structure`]: a staged structure change set generated by
//! `Driver::alter_sql` and committed with `Editor::commit_ddl` changes the
//! table as staged, keeps its rows, and invalid sets are refused before any
//! SQL runs.

use openrows_driver_api::schema::{
    DefaultValue, IndexMethod, NewColumn, NewIndex, SchemaChange, TableDetail,
};
use openrows_driver_api::structure::AlterTable;
use openrows_driver_api::{Connection, catalog, editor};

use crate::dialect::create_table;
use crate::sink::{query, run_all};
use crate::{Failure, Group, Target, ensure, fixture_name};

pub(crate) async fn run(target: &Target) -> Result<(), Failure> {
    let dialect = target.driver.dialect();
    let table = fixture_name(Group::Structure, "t");
    let relation = dialect
        .qualified(&target.schema, &table)
        .map_err(|error| Failure::Setup(error.to_string()))?;
    let mut connection = target.connect().await?;
    run_all(
        connection.as_mut(),
        &[
            create_table(&relation),
            format!("INSERT INTO {relation} (id, name, note) VALUES (1, 'one', 'a')"),
        ],
    )
    .await?;
    let outcome = alter(target, connection.as_mut(), (&table, &relation)).await;
    query(connection.as_mut(), &format!("DROP TABLE {relation}")).await?;
    connection.close().await?;
    outcome
}

fn changes(index: &str) -> Vec<SchemaChange> {
    vec![
        SchemaChange::ColumnType {
            column: "name".into(),
            data_type: "VARCHAR(80)".into(),
        },
        SchemaChange::RenameColumn {
            column: "note".into(),
            name: "memo".into(),
        },
        SchemaChange::AddColumn(NewColumn {
            name: "qty".into(),
            data_type: "INTEGER".into(),
            nullable: true,
            default: DefaultValue::Literal("1".into()),
            comment: None,
        }),
        SchemaChange::CreateIndex(NewIndex {
            name: Some(index.to_owned()),
            // An added column: `MySQL` cannot index the `TEXT` note without a prefix.
            columns: vec!["qty".into()],
            unique: false,
            method: IndexMethod::Btree,
        }),
    ]
}

async fn detail(
    target: &Target,
    connection: &mut dyn Connection,
    table: &str,
) -> Result<TableDetail, Failure> {
    Ok(catalog(connection)?
        .table_detail(&target.schema, table)
        .await?)
}

async fn alter(
    target: &Target,
    connection: &mut dyn Connection,
    (table, relation): (&str, &str),
) -> Result<(), Failure> {
    let before = detail(target, connection, table).await?;
    let place = |detail| AlterTable {
        schema: &target.schema,
        table,
        detail,
    };
    let missing = [SchemaChange::DropColumn("orc_missing".into())];
    ensure(
        target.driver.alter_sql(&place(&before), &missing).is_err(),
        || "dropping an unknown column was not refused".to_owned(),
    )?;
    let index = fixture_name(Group::Structure, "i");
    let plan = target
        .driver
        .alter_sql(&place(&before), &changes(&index))
        .map_err(|error| Failure::Contract(format!("alter_sql: {error}")))?;
    editor(connection)?.commit_ddl(&plan.statements).await?;
    let after = detail(target, connection, table).await?;
    let names: Vec<&str> = after.columns.iter().map(|c| c.name.as_str()).collect();
    ensure(names == ["id", "name", "memo", "qty"], || {
        format!("columns after the change set: {names:?}")
    })?;
    let name_type = after.columns[1].data_type.to_ascii_lowercase();
    ensure(name_type.contains("80"), || format!("name is {name_type}"))?;
    ensure(after.indexes.iter().any(|i| i.name == index), || {
        format!("index {index} missing: {:?}", after.indexes)
    })?;
    let (rows, _) = query(
        connection,
        &format!("SELECT memo FROM {relation} WHERE qty = 1 AND name = 'one'"),
    )
    .await?;
    let memo = rows.single()?;
    ensure(memo.as_deref() == Some("a"), || {
        format!("the row after the change set: {memo:?}")
    })
}
